paragraph.math:
$$\begin{array}{l}
  {{f^{\prime}{(x)}} = \frac{(x\ln x){(0)} - {(1)}(\ln x + 1)}{\left\lbrack x(\ln x) \right\rbrack^{2}}} \\
  {\phantom{f^{\prime}{(x)}} = {- \frac{\ln x + 1}{\left\lbrack x(\ln x) \right\rbrack^{2}}}}
  \end{array}$$

$$\begin{array}{l}
  {{\int_{2}^{\infty}{\frac{1}{x\ln x}\mathit{dx}}} = {\lim\limits_{b\rightarrow\infty}{\int_{2}^{b}{\frac{1}{x\ln x}\mathit{dx}}}}} \\
  {\phantom{\int_{2}^{\infty}{\frac{1}{x\ln x}\mathit{dx}}} = {\lim\limits_{b\rightarrow\infty}{\lbrack\ln(\ln x)\rbrack}_{2}^{b}}} \\
  {\phantom{\int_{2}^{\infty}{\frac{1}{x\ln x}\mathit{dx}}} = {\lim\limits_{b\rightarrow\infty}\lbrack\ln(\ln b) - \ln(\ln 2)\rbrack}} \\
  {\phantom{\int_{2}^{\infty}{\frac{1}{x\ln x}\mathit{dx}}} = \infty}
  \end{array}$$

$$\begin{array}{l}
  {{f(x)} = \frac{1}{1 + x}} \\
  {\phantom{f{(x)}} = {1 + ( - x) + ( - x)^{2} + \cdots + ( - x)^{n} + \cdots}} \\
  {\phantom{f(x)} = {1 - x + x^{2} - x^{3} + \cdots + ( - 1)^{n}x^{n} + \cdots}( - 1 < x < 1)}
  \end{array}$$

$$\begin{array}{l}
  {{f\left( x) \right.} = {\frac{x}{1 + x^{2}} = x\left\lbrack \frac{1}{1 - \left( - x^{2}) \right.} \right\rbrack}} \\
  {\phantom{f\left( x) \right.} = {x\lbrack 1 + ( - x^{2}) + {( - x^{2})}^{2} + {( - x^{2})}^{3} + \cdots + {( - x^{2})}^{n} + \cdots\rbrack}} \\
  {\phantom{f{(x)}} = {x - x^{3} + x^{5} - x^{7} + \cdots + {( - 1)}^{n}x^{2n + 1} + \cdots}}
  \end{array}$$

$$\begin{array}{l}
  {e^{- x^{2}} = {1 + ( - x^{2}) + \frac{\left( - x^{2} \right)^{2}}{2!}}} \\
  {\phantom{e^{- x^{2}}}\quad{+ \frac{\left( - x^{2} \right)^{3}}{3!} + \cdots + \frac{\left( - x^{2} \right)^{n}}{n!} + \cdots}} \\
  {\phantom{e^{- x^{2}}} = {1 - x^{2} + \frac{x^{4}}{2!} - \frac{x^{6}}{3!} + \cdots + \frac{( - 1)^{n}x^{2n}}{n!} + \cdots}}
  \end{array}$$

$$\begin{array}{l}
  {{\int_{0}^{0.5}{xe^{- x^{2}}\mathit{dx}}} = \left. {- \frac{1}{2}e^{- x^{2}}} \right|_{0}^{0.5}\qquad{\text{Use the substitution}u = x^{2}\text{.}}} \\
  {\phantom{\int_{0}^{0.5}{xe^{- x^{2}}\mathit{dx}}} = - \frac{1}{2}(e^{- 0.25} - 1)}
  \end{array}$$
